let helpAnswer='',modalOpen=false,alphaLessonId=null,pendingChallenge=null,pendingTour=null,pendingInvite=null,pendingTutorial=false,renderedView=null,installPrompt=null,sharedLink='',homeTab='play',preparation=null;
