function sanitizeSession(g) {
 try {
  if(!g||![5,6].includes(g.version)||!UNIT.has(g.unit)||!MODES.includes(g.mode)||!LANGS.includes(g.target)||!LANGS.includes(g.support)||g.route!==`${g.support}>${g.target}`)return null;
  if(typeof g.id!=='string'||g.id.length>80||!['playing','roundDone'].includes(g.phase))return null;
  if(!Array.isArray(g.pool)||g.pool.length<1||g.pool.length>12||g.pool.some(id=>!ITEM.has(id)))return null;
  if(!Array.isArray(g.board)||!g.board.length||g.board.length>120)return null;
  const ids=new Set(),positions=new Set();
  for(const tile of g.board){
   if(!Number.isInteger(tile.id)||tile.id<0||ids.has(tile.id)||!g.pool.includes(tile.itemId)||!LANGS.includes(tile.lang)||!Number.isInteger(tile.x)||tile.x<0||tile.x>10||!Number.isInteger(tile.y)||tile.y<0||tile.y>30||![0,1,2,3].includes(tile.z)||typeof tile.gone!=='boolean'||!['target','support','word'].includes(tile.type)||typeof tile.text!=='string'||tile.text.length>200)return null;
   const item=ITEM.get(tile.itemId);
   if(tile.type==='target'&&(tile.lang!==g.target||tile.text!==item.text[g.target]))return null;
   if(tile.type==='support'&&(tile.lang!==g.support||tile.text!==supportText(item,g.target,g.support)))return null;
   if(tile.type==='word'&&(tile.lang!==g.target||!tokens(item.text[g.target]).includes(tile.text)))return null;
   const at=`${tile.x}:${tile.y}:${tile.z}`;if(positions.has(at))return null;ids.add(tile.id);positions.add(at);
  }
  if(!Array.isArray(g.completed)||g.completed.some(id=>!g.pool.includes(id))||new Set(g.completed).size!==g.completed.length)return null;
  if(!Array.isArray(g.results)||g.results.length>12||g.results.some(r=>!r||!g.pool.includes(r.itemId)||!Number.isFinite(r.mistakes)))return null;
  if(!Array.isArray(g.prefix)||g.prefix.length>120||g.prefix.some(x=>!x||!ids.has(x.id)||typeof x.text!=='string'||x.text.length>200))return null;
  if(!g.helpUses||!['hint','shuffle'].every(k=>Number.isInteger(g.helpUses[k])&&g.helpUses[k]>=0&&g.helpUses[k]<=10000))return null;
  if(!['score','combo','bestCombo','errors','tries','round'].every(k=>Number.isFinite(g[k])&&g[k]>=0&&g[k]<=100000))return null;
  if(!g.assist||!g.mistakes||typeof g.assist!=='object'||typeof g.mistakes!=='object')return null;
  const out=clone(g);out.version=6;out.history=[];out.tableFormat=Object.hasOwn(TABLE_FORMATS,g.tableFormat)?g.tableFormat:'classic';out.challengeDay=/^\d{4}-\d{2}-\d{2}$/.test(g.challengeDay)?g.challengeDay:null;out.seed=Number.isInteger(g.seed)?g.seed>>>0:0;out.tourId=typeof g.tourId==='string'&&/^[a-z0-9_]{1,80}$/.test(g.tourId)?g.tourId:null;out.tourStage=Number.isInteger(g.tourStage)&&g.tourStage>=0&&g.tourStage<3?g.tourStage:null;out.tutorial=Boolean(g.tutorial);out.inviteTarget=Number.isFinite(g.inviteTarget)?Math.max(0,Math.min(10000,g.inviteTarget)):null;
  for(const k of ['heard','revealed'])out[k]=Array.isArray(g[k])?[...new Set(g[k].filter(id=>g.pool.includes(id)))]:[];
  out.hints=Array.isArray(g.hints)?g.hints.filter(id=>ids.has(id)):[];
  out.assist={};out.mistakes={};for(const id of g.pool){if(g.assist[id])out.assist[id]=true;if(Number.isFinite(g.mistakes[id]))out.mistakes[id]=Math.min(10000,Math.max(0,Math.floor(g.mistakes[id])));}
  out.pairSelected=ids.has(g.pairSelected)?g.pairSelected:null;
  if(g.helpPending){const h=g.helpPending;if(!['hint','shuffle'].includes(h.kind)||!ITEM.has(h.itemId))return null;out.helpPending={kind:h.kind,itemId:h.itemId,tries:Math.max(0,Math.min(10000,Number(h.tries)||0)),answer:String(h.answer||'').slice(0,500),guided:Boolean(h.guided),error:typeof h.error==='string'?h.error:false};}
  out.writePending=null;
  if(g.writePending){const w=g.writePending;if(!ids.has(w.tileId)||!g.pool.includes(w.itemId))return null;out.writePending={tileId:w.tileId,itemId:w.itemId,tries:Math.max(0,Math.min(10000,Number(w.tries)||0)),answer:String(w.answer||'').slice(0,500),guided:Boolean(w.guided),error:typeof w.error==='string'?w.error:false};}
  if(g.feedback&&(!UI.it[g.feedback.key]||g.feedback.item&&!ITEM.has(g.feedback.item)))out.feedback=null;
  return out;
 }catch{return null;}
}
function validSession(g){return Boolean(sanitizeSession(g));}
function cleanSaved(p){const clean=validateProgress(p);clean.sessions={};for(const [k,g]of Object.entries(p.sessions||{}).slice(0,16)){const session=sanitizeSession(g);if(session&&k===session.route)clean.sessions[k]=session;}for(const [lang,session]of Object.entries(clean.alphabetSessions)){const lesson=ALPHABET[lang]?.lessons.find(l=>l.id===session.lesson);if(!lesson||session.queue.some(id=>!lesson.cards.some(c=>c.id===id)))delete clean.alphabetSessions[lang];}for(const [route,tour]of Object.entries(clean.tours))if(tour.units.some(id=>!UNIT.has(id)))delete clean.tours[route];return clean;}
function freshSaved(){const p=newProgress();p.sessions={};return p;}
function load(){try{const result=loadSaved(localStorage,KEY,cleanSaved,freshSaved,['parola-mahjong-v5','parola-mahjong-v5.backup']);storageOK=result.ok;return result.value;}catch{storageOK=false;return freshSaved();}}
function save(){if(game&&view==='game')store.sessions[game.route]=game;try{storageOK=saveSafely(localStorage,KEY,store,cleanSaved);}catch{storageOK=false;}}
function t(key,vars={}){let s=UI[store.settings.ui]?.[key];if(s==null){console.error('Missing translation',key);s=`[${key}]`;}return s.replace(/\{(\w+)\}/g,(_,k)=>vars[k]??`{${k}}`);}
function dir(l){return l==='ar'?'rtl':'ltr';}
function route(){return routeKey(store.settings);}
function missionKey(unit,mode,r=route()){return`${r}|${mode}|${unit}`;}
function unitItems(u){return UNIT.get(u).items.map(id=>ITEM.get(id));}
function title(u){return UNIT.get(u).title[store.settings.ui];}
function modeName(mode){return t(mode==='listen'?'listen':mode);}
function modeIcon(mode){return mode==='listen'?'ear':mode;}
function totalXP(){return Math.floor(Object.values(store.missions).reduce((n,m)=>n+m.score,0)/10)+progressionBonus(store.daily);}
function dayActivity(day=localDay()){return store.daily[day]||(store.daily[day]={games:[],answers:[],alphabet:[],reviews:[],formats:[],bestCombo:0,challenges:{}});}
function recordIndependent(key,alphabet=false,review=false){const d=dayActivity();if(!d.answers.includes(key))d.answers.push(key);if(alphabet&&!d.alphabet.includes(key))d.alphabet.push(key);if(review&&!d.reviews.includes(key))d.reviews.push(key);}
function todaysChallenge(){const day=localDay(),saved=store.daily[day]?.challenges[route()];const known=Object.keys(store.missions).filter(k=>k.startsWith(route()+'|')&&MODES.includes(k.split('|')[1])).map(k=>UNIT.get(k.split('|')[2])?.index??0);const pool=COURSE.units.slice(0,Math.min(COURSE.units.length,Math.max(0,...known)+3));const plan=challengePlan(day,route(),pool);return saved&&UNIT.has(saved.unit)?{...plan,unit:saved.unit,mode:saved.mode,completed:saved.completed}:plan;}
function progressionPanel(){const level=playerLevel(totalXP()),challenge=todaysChallenge(),goals=dailyGoals(store.daily[localDay()]),awards=earnedBadges(store);return `<section class="game-hub"><div class="player-line"><div class="player-rank">${icon('spark',24)}<div><strong>${esc(t('playerLevel',{n:level.level}))}</strong><span>${esc(t('nextPlayerLevel',{n:level.remaining}))}</span></div></div><progress max="${level.needed}" value="${level.current}" aria-label="${esc(t('playerLevel',{n:level.level}))}"></progress><button class="textbtn" data-action="achievements">${icon('trophy',21)}${esc(t('achievements'))}<span>${awards.length}/${BADGES.length}</span></button></div>${store.sessions[route()]?`<div class="resume-strip"><span>${esc(t('activeTable'))} · ${esc(title(store.sessions[route()].unit))}</span>${button('resume',t('resume'),'play','secondary small')}</div>`:''}<div class="daily-stage"><div class="daily-lead"><h1>${esc(t('dailyHeadline'))}</h1><span class="daily-label">${icon('shuffle',18)}${esc(t('dailyChallenge'))}</span><p><strong>${esc(title(challenge.unit))}</strong> · ${esc(modeName(challenge.mode))}</p><p class="daily-description">${esc(t(challenge.completed?'dailyCompleted':'dailyIntro'))}</p>${button('dailyChallenge',t(challenge.completed?'replayDaily':'startDaily'),'play','coral')}<span class="daily-reward">${esc(t(challenge.completed?'challengeRewardDone':'challengeReward'))}</span></div><aside class="daily-goals"><h2>${esc(t('dailyGoals'))}</h2>${goals.map(goal=>`<div class="daily-goal ${goal.current>=goal.total?'is-done':''}"><span class="goal-check">${goal.current>=goal.total?icon('check',18):icon(goal.id==='table'?'tile':goal.id==='answers'?'shield':'alpha',18)}</span><span>${esc(t('goal_'+goal.id))}</span><b>${Math.min(goal.current,goal.total)}/${goal.total}</b></div>`).join('')}<p>${esc(t('dailyGoalReward'))}</p></aside></div></section>`;}
function formatControls(){if(!['pair','listen','write'].includes(selectedMode))return `<p class="format-note">${esc(t('sentenceFormat'))}</p>`;const selected=pendingTour?TOUR_FORMATS[pendingTour.stage]:pendingInvite?pendingInvite.tableFormat:pendingTutorial?'focus':pendingChallenge?'explorer':store.settings.tableFormat;return `<fieldset class="table-formats"><legend>${esc(t('tableSize'))}</legend><div>${Object.entries(TABLE_FORMATS).map(([format,count])=>`<button type="button" data-action="tableFormat" data-format="${format}" aria-pressed="${selected===format}" ${pendingChallenge||pendingTour||pendingInvite||pendingTutorial?'disabled':''}><strong>${esc(t('format_'+format))}</strong><span>${esc(t('tileCount',{n:count*2}))}</span></button>`).join('')}</div></fieldset>`;}
function achievementsView(){const awards=earnedBadges(store),symbols={first:'tile',mono:'globe',traveller:'path',alphabet:'alpha',writer:'write',combo:'flame',explorer:'grid',habit:'clock',tour:'path'};return `<section class="achievements"><button class="textbtn" data-action="nav" data-view="home">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('achievements'))}</h1><p>${esc(t('achievementsDesc'))}</p></div><ul class="achievement-list">${BADGES.map(id=>`<li class="${awards.includes(id)?'is-earned':''}"><span class="achievement-icon">${icon(symbols[id],28)}</span><div><h2>${esc(t('badge_'+id))}</h2><p>${esc(t('badge_'+id+'_desc'))}</p></div><span class="achievement-state">${awards.includes(id)?icon('check',21):esc(t('stillToEarn'))}</span></li>`).join('')}</ul></section>`;}
function summaryRewards(summary){return `<div class="summary-rewards">${summary.bonus?`<p>${icon('spark',20)}${esc(t('bonusEarned',{n:summary.bonus}))}</p>`:''}${summary.newBadges?.length?`<p>${icon('trophy',20)}${esc(t('newAchievement'))}: ${summary.newBadges.map(id=>esc(t('badge_'+id))).join(' · ')}</p>`:''}${summary.challengeDay?`<p>${icon('shuffle',20)}${esc(t('dailyCompleted'))}</p>`:''}<button class="textbtn" data-action="achievements">${esc(t('achievements'))}${icon('arrow',18,'right-arrow')}</button></div>`;}
function gameFlowStrip(){return `<div class="game-flow-strip"><span>${icon('tile',17)}${esc(t(['complete','compose'].includes(game.mode)?'remainingSentences':'remainingPairs',{n:game.pool.length-game.completed.length}))}</span><span class="flow-combo ${game.combo>=3?'is-hot':''}">${icon('flame',18)}${esc(t('combo'))} ${game.combo}</span><span>${esc(t(game.challengeDay?'dailyChallenge':game.tableFormat==='explorer'?'format_explorer':game.tableFormat==='focus'?'format_focus':'format_classic'))}</span></div>`;}
function welcomeView(){return `${invitationPanel()}<section class="welcome"><div class="welcome-copy"><h1>${esc(t('welcomeTitle'))}</h1><p>${esc(t('welcomeBody'))}</p><div class="welcome-demonstration" aria-hidden="true"><span>Ciao!</span><span>Hello!</span>${icon('pair',30)}</div></div><div class="welcome-setup"><h2>${esc(t('welcomeChoose'))}</h2>${langSelect('welcome-target',store.settings.target,t('targetLanguage'))}${langSelect('welcome-support',store.settings.support,t('supportLanguage'))}<p class="tiny-note">${esc(t('welcomeMono'))}</p><div class="field"><label for="welcome-entry">${esc(t('welcomeReadiness'))}</label><select id="welcome-entry"><option value="play">${esc(t('welcomePlay'))}</option><option value="alphabet">${esc(t('fromAlphabet'))}</option></select></div>${button('welcomeStart',t('welcomeStart'),'play','coral wide')}<button class="textbtn welcome-skip" data-action="welcomeSkip">${esc(t('welcomeSkip'))}${icon('arrow',18,'right-arrow')}</button><p class="tiny-note">${esc(t('welcomePrivacy'))}</p></div></section>`;}
function completeWelcome(){const target=document.querySelector('#welcome-target').value,support=document.querySelector('#welcome-support').value,entry=document.querySelector('#welcome-entry').value;store.settings={...store.settings,target,support,ui:target===support?target:store.settings.ui};store.onboarded=true;save();if(entry==='alphabet'){alphaDialog();return;}intro('greetings','pair',null,{tutorial:true});startGame();}
function tutorialPanel(){if(!game?.tutorial)return '';return `<div class="tutorial-panel" role="status">${icon('hint',24)}<div><strong>${esc(t(game.completed.length?'tutorialContinue':'tutorialFirst'))}</strong><p>${esc(t(game.completed.length?'tutorialNext':game.support===game.target?'tutorialRuleMono':'tutorialRule'))}</p></div><span>${game.completed.length}/3</span></div>`;}
function adventurePanel(){const tour=store.tours[route()],active=tour&&tour.stage<3,found=collectionItems(store.memory,route(),[...COURSE.items,...COURSE.vocab]);return `<section class="adventure-panel"><div class="adventure-lead"><h2>${esc(t('tourTitle'))}</h2><p>${esc(t('tourBody'))}</p><div class="adventure-steps" aria-label="${esc(t('tourProgress'))}">${[0,1,2].map(stage=>`<span class="${active&&stage<tour.stage?'is-done':''}">${icon(active&&stage<tour.stage?'check':['pair','complete','write'][stage],20)}${esc(t('tourStep',{n:stage+1}))}</span>`).join('')}</div>${button('tour',t(active?'resumeTour':'startTour'),'path','coral')}<button class="textbtn" data-action="passport">${icon('book',19)}${esc(t('passport'))} · ${found.length}/78</button></div><div class="adventure-preview" aria-hidden="true">${unitItems(active?tour.units[tour.stage]:'greetings').map(item=>`<span lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(item.text[store.settings.target])}</span>`).join('')}</div></section><details class="app-utilities" data-disclosure="utilities"><summary>${esc(t('moreOptions'))}${icon('down',16)}</summary><div class="app-utility-actions"><button class="textbtn" data-action="shareChallenge">${icon('globe',17)}${esc(t('challengeFriend'))}</button><button class="textbtn" data-action="installApp">${icon('download',17)}${esc(t('installApp'))}</button><a class="textbtn" href="./Parola-offline.html" download="Parola-offline.html">${icon('download',17)}${esc(t('downloadOffline'))}</a></div></details>`;}
function beginTour(){let tour=store.tours[route()];if(!tour||tour.stage===3){const reached=Object.keys(store.missions).filter(key=>key.startsWith(route()+'|')&&MODES.includes(key.split('|')[1])).map(key=>UNIT.get(key.split('|')[2])?.index??-1),start=Math.min(COURSE.units.length-3,Math.max(-1,...reached)+1);tour={id:Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7),units:COURSE.units.slice(start,start+3).map(unit=>unit.id),stage:0,score:0};store.tours[route()]=tour;save();}const session=store.sessions[route()];if(session?.tourId===tour.id&&session.tourStage===tour.stage){resume();return;}intro(tour.units[tour.stage],TOUR_MODES[tour.stage],null,{tour});startGame();}
function tourGamePanel(){if(game?.inviteTarget!==null&&game?.inviteTarget!==undefined)return `<div class="tour-game-panel"><strong>${esc(t('inviteTitle'))}</strong><span>${esc(t('inviteGoal',{n:game.inviteTarget}))}</span></div>`;if(!game?.tourId)return '';return `<div class="tour-game-panel"><strong>${esc(t('tourTitle'))}</strong><span>${esc(t('tourStage',{n:game.tourStage+1}))}</span><progress max="3" value="${game.tourStage}" aria-label="${esc(t('tourProgress'))}"></progress></div>`;}
function tourSummary(summary){if(summary.inviteTarget!==null&&summary.inviteTarget!==undefined)return `<div class="first-win"><h2>${esc(t(summary.score>=summary.inviteTarget?'inviteWon':'inviteRetry'))}</h2><p>${esc(t('inviteResult',{score:summary.score,target:summary.inviteTarget}))}</p>${button('shareChallenge',t('challengeFriend'),'globe','coral')}</div>`;if(summary.tutorial)return `<div class="first-win"><h2>${esc(t('firstWinTitle'))}</h2><p>${esc(t('firstWinBody'))}</p>${button('tour',t('startTour'),'path','coral')}</div>`;if(!summary.tourId)return '';const tour=store.tours[summary.route],complete=tour?.stage===3;return `<div class="first-win"><h2>${esc(t(complete?'tourComplete':'tourCheckpoint'))}</h2><p>${esc(t(complete?'tourCompleteBody':'tourCheckpointBody'))}</p>${tour?`<p>${esc(t('tourTotal',{n:tour.score}))}</p>`:''}${button(complete?'passport':'tour',t(complete?'openPassport':'continueTour'),complete?'book':'path','coral')}</div>`;}
function passportView(){const all=[...COURSE.items,...COURSE.vocab].sort((a,b)=>UNIT.get(a.unitId).index-UNIT.get(b.unitId).index),found=new Set(collectionItems(store.memory,route(),all).map(item=>item.id));return `<section class="passport"><button class="textbtn" data-action="nav" data-view="home">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('passport'))}</h1><p>${esc(t('passportBody'))}</p><p class="passport-count">${found.size}/78 · <bdi>${NAMES[store.settings.target]}</bdi></p></div><div class="passport-grid">${all.map(item=>`<article class="passport-stamp ${found.has(item.id)?'is-collected':'is-locked'}"><span>${esc(title(item.unitId))}</span>${found.has(item.id)?`<h2 lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(item.text[store.settings.target])}</h2>${sounds(store.settings.target,item.text[store.settings.target],item.id)}`:`<div class="passport-lock">${icon('book',28)}</div><p>${esc(t('stampLocked'))}</p>`}</article>`).join('')}</div></section>`;}
function invitationPanel(){return invitation?`<section class="invitation-panel"><div><h2>${esc(t('inviteTitle'))}</h2><p>${esc(title(invitation.unit))} · ${esc(modeName(invitation.mode))} · ${esc(t('inviteScore',{n:invitation.score}))}</p></div>${button('acceptInvite',t('acceptInvite'),'play','coral')}</section>`:'';}
function acceptInvitation(){if(!invitation)return;const [support,target]=invitation.route.split('>');store.settings={...store.settings,support,target};store.onboarded=true;save();intro(invitation.unit,invitation.mode,null,{invite:invitation});startGame();}
async function shareChallenge(){const plan=lastSummary&&view==='summary'?lastSummary:{...todaysChallenge(),route:route(),tableFormat:'explorer',score:0};sharedLink=challengeURL('https://matteoawi.github.io/parola/',{...plan,seed:plan.seed??seedFor(localDay()+'|'+route())});if(navigator.share){try{await navigator.share({title:'Parola',text:t('shareText'),url:sharedLink});return;}catch(error){if(error.name==='AbortError')return;}}nav('share');}
function shareView(){return `<section class="share-page"><button class="textbtn" data-action="nav" data-view="home">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('challengeFriend'))}</h1><p>${esc(t('shareBody'))}</p></div><label for="challenge-link">${esc(t('challengeLink'))}</label><input id="challenge-link" type="url" readonly value="${esc(sharedLink)}">${button('copyChallenge',t('copyLink'),'globe','coral')}<p class="tiny-note">${esc(t('sharePrivacy'))}</p></section>`;}
