function sizeBoard(){const el=document.querySelector('.board');if(!el||!game)return;el.style.removeProperty('--th');const tile=el.querySelector('.tile'),w=tile?.offsetWidth||100;let h=tile?.offsetHeight||120;if(matchMedia(MOBILE_QUERY).matches){const textHeight=Math.max(0,...[...el.querySelectorAll('.tiletext')].map(text=>text.scrollHeight));h=Math.max(h,textHeight+49);el.style.setProperty('--th',h+'px');}const gap=parseFloat(getComputedStyle(el).getPropertyValue('--gap'))||8,cols=Math.max(...game.board.map(t=>t.x))+1,rows=Math.max(...game.board.map(t=>t.y))+1;el.style.width=`${cols*(w+gap)-gap+7}px`;el.style.height=`${rows*(h+gap)-gap+6}px`;}
