function snapshot(){return clone({board:game.board,pairSelected:game.pairSelected,prefix:game.prefix,completed:game.completed,results:game.results,score:game.score,combo:game.combo,round:game.round,phase:game.phase});}
function pushHistory(){game.history.push(snapshot());if(game.history.length>100)game.history.shift();}
function undo(){if(!game||game.phase==='roundDone'||!game.history.length)return;Object.assign(game,game.history.pop());game.feedback=null;game.hints=[];render();toast(t('restoreSentence'));}
function incorrect(key,ids=[]){game.errors++;game.tries++;game.combo=0;for(const id of ids)game.mistakes[id]=(game.mistakes[id]||0)+1;game.feedback={key,kind:'warn'};game.hints=[];fx(false);render();announcer.textContent=t(key);}
async function tileAudio(id){if(!game)return;const tile=game.board.find(t=>t.id===id);if(!tile||tile.gone)return;const idGame=game.id;if(game.mode==='write'&&tile.type==='target'&&!game.revealed.includes(tile.itemId)){game.assist[tile.itemId]=true;save();}const ok=await player.speak(tile.lang,tile.text,{preference:store.settings.voice,context:tile.itemId});if(ok&&game?.id===idGame&&tile.type==='target'){if(!game.heard.includes(tile.itemId))game.heard.push(tile.itemId);save();}}
function addResult(item,points){const assisted=Boolean(game.assist[item.id]);game.tries++;game.combo++;game.bestCombo=Math.max(game.bestCombo,game.combo);game.score+=points+(assisted||game.mistakes[item.id]?0:20)+Math.min(game.combo-1,4)*5;game.completed.push(item.id);game.results.push({itemId:item.id,assisted,mistakes:game.mistakes[item.id]||0});game.feedback={key:game.mode==='pair'||game.mode==='listen'||game.mode==='write'?'pairOk':'sentenceOk',kind:'success',item:item.id};fx(true);}
function pickTile(id){if(!game||game.phase!=='playing'||game.helpPending||game.writePending)return;const tile=game.board.find(t=>t.id===id);if(!tile||tile.gone)return;if(!free(tile,game.board)){toast(t('blocked'));return;}
 if(game.mode==='write'&&tile.type==='target'&&!game.revealed.includes(tile.itemId)){beginWrite(tile);return;}
 game.hints=[];
 if(game.mode==='pair'||game.mode==='listen'||game.mode==='write'){
  if(game.mode==='listen'&&tile.type==='target')tileAudio(id);
  if(game.pairSelected===id){game.pairSelected=null;render();return;}
  if(game.pairSelected==null){game.pairSelected=id;render();return;}
  const other=game.board.find(t=>t.id===game.pairSelected);
  if(tile.pairKey!==other.pairKey||tile.type===other.type){game.pairSelected=null;incorrect('pairWrong',[tile.itemId,other.itemId]);return;}
  if(game.mode==='listen'&&!game.transcript&&!game.heard.includes(tile.itemId)){game.pairSelected=tile.type==='target'?tile.id:other.id;render();toast(t('audioNeedListen'));return;}
  pushHistory();tile.gone=true;other.gone=true;game.pairSelected=null;const item=ITEM.get(tile.itemId);if(game.transcript)game.assist[item.id]=true;addResult(item,game.mode==='write'?60:30);if(game.completed.length===game.pool.length){finish();return;}render();player.speak(game.target,item.text[game.target],{preference:store.settings.voice,context:item.id});return;
 }
 const word=tile.text,prefix=[...game.prefix.map(p=>p.text),word];
 if(game.mode==='complete'){
  const item=unitItems(game.unit)[game.round];if(!prefixMatch(prefix,item.text[game.target],game.target)){incorrect('prefixWrong',[item.id]);return;}
  pushHistory();tile.gone=true;game.prefix.push({id,text:word});game.feedback=null;
  if(game.prefix.length===tokens(item.text[game.target]).length){addResult(item,80);game.history=[];if(game.completed.length===3){finish();return;}game.phase='roundDone';render();player.speak(game.target,item.text[game.target],{preference:store.settings.voice,context:item.id});return;}
 }else{
  const after=game.board.map(t=>({...t,gone:t.gone||t.id===id}));const opts=sentenceOptions(unitItems(game.unit),prefix,after,game.target,game.completed);
  if(!opts.length){incorrect('prefixWrong',unitItems(game.unit).filter(i=>!game.completed.includes(i.id)).map(i=>i.id));return;}
  pushHistory();tile.gone=true;game.prefix.push({id,text:word});game.feedback=null;
 }
 ensureNext();render();
}
function expectedContinuation(){if(game.mode==='complete'){const items=unitItems(game.unit);return [ ...tokens(items[game.round].text[game.target]).slice(game.prefix.length),...items.slice(game.round+1).flatMap(i=>tokens(i.text[game.target]))];}
 const opts=sentenceOptions(unitItems(game.unit),game.prefix.map(p=>p.text),game.board,game.target,game.completed);return opts[0]?.remaining||[];}
function ensureNext(){if(!['complete','compose'].includes(game.mode)||game.phase!=='playing')return;const expect=expectedContinuation();if(!expect.length)return;if(sequenceHint(game.board,expect[0],game.target).length)return;
 // Another valid sentence may be open. Do not unnecessarily rearrange the board.
 if(game.mode==='compose'){
  const opts=sentenceOptions(unitItems(game.unit),game.prefix.map(p=>p.text),game.board,game.target,game.completed);
  if(opts.some(o=>!o.remaining.length||sequenceHint(game.board,o.remaining[0],game.target).length))return;
 }
 game.board=repairSequence(game.board,expect,game.target);game.feedback={key:'boardReset',kind:''};
}
function checkSentence(){if(!game||game.mode!=='compose'||game.phase!=='playing')return;const text=game.prefix.map(p=>p.text).join(' '),item=unitItems(game.unit).find(i=>matchesText(i,text,game.target));if(!item){incorrect(game.prefix.length?'notComplete':'empty');return;}if(game.completed.includes(item.id)){incorrect('alreadyFound');return;}addResult(item,100);game.history=[];if(game.completed.length===3){finish();return;}game.phase='roundDone';render();player.speak(game.target,item.text[game.target],{preference:store.settings.voice,context:item.id});}
function nextRound(){if(!game||game.phase!=='roundDone')return;game.prefix=[];game.round++;game.phase='playing';game.feedback=null;game.history=[];
 if(game.mode==='compose'){game.board=makeSequence(payloadsFor(shuffled(unitItems(game.unit).filter(i=>!game.completed.includes(i.id))),game.target));game.feedback={key:'refill',kind:''};}else ensureNext();render();}
function markHelp(){if(['pair','listen','write'].includes(game.mode)){for(const tile of game.board.filter(t=>!t.gone&&game.hints.includes(t.id)))game.assist[tile.itemId]=true;}else if(game.mode==='complete')game.assist[unitItems(game.unit)[game.round].id]=true;else for(const i of unitItems(game.unit).filter(i=>!game.completed.includes(i.id)))game.assist[i.id]=true;}
function applyHelp(kind){if(!game||game.phase!=='playing')return;
 if(kind==='hint'){
  if(['pair','listen','write'].includes(game.mode))game.hints=pairHint(game.board);
  else{ensureNext();const words=expectedContinuation();if(words.length)game.hints=sequenceHint(game.board,words[0],game.target);}
  markHelp();toast(t('hintReady'));
 }else{
  if(['pair','listen','write'].includes(game.mode)){const remaining=game.pool.filter(id=>!game.completed.includes(id)).map(id=>ITEM.get(id));game.board=makePairs(shuffled(remaining),game.target,game.support,Math.random,game.board);game.pairSelected=null;}
  else{const words=expectedContinuation();game.board=repairSequence(game.board,words,game.target);}
  game.hints=[];game.history=[];toast(t('shuffleReady'));
 }
 game.helpUses[kind]++;render();
}
function requestHelp(kind){if(!game||game.phase!=='playing'||game.writePending||!['hint','shuffle'].includes(kind))return;if(game.helpPending){openHelpDialog();return;}if(game.helpUses[kind]===0){applyHelp(kind);return;}
 const known=unitItems(game.unit).filter(item=>wasIntroduced(store,phraseMaterial(item,game.target,game.support))),currentItems=known.length?known:game.pool.map(id=>ITEM.get(id)),item=currentItems[(game.helpUses.hint+game.helpUses.shuffle-1)%currentItems.length];game.helpPending={kind,itemId:item.id,tries:0,answer:'',guided:false,error:false};save();openHelpDialog();}
function modal(html,after=()=>{}){closeDialog();const d=document.createElement('dialog');d.className='modal';d.innerHTML=html;document.body.append(d);d.showModal();if(!matchMedia('(prefers-reduced-motion:reduce)').matches)d.animate([{opacity:.65,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:200,easing:'cubic-bezier(.16,1,.3,1)'});modalOpen=true;d.addEventListener('cancel',()=>{modalOpen=false;if(game?.helpPending){game.helpPending=null;save();}if(game?.writePending){game.writePending=null;save();}});after(d);return d;}
function closeDialog(){document.querySelector('dialog.modal')?.remove();modalOpen=false;}
function keyboard(lang){const chars={it:'à è é ì ò ù',en:"'",ru:'а б в г д е ё ж з и й к л м н о п р с т у ф х ц ч ш щ ъ ы ь э ю я',ar:'ا أ إ آ ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن ه و ي ة ى ء ؤ ئ'}[lang].split(' ');return `<div class="keyboard" aria-label="${esc(t('keyboard'))}">${chars.map(c=>`<button class="keybtn" data-action="key" data-char="${esc(c)}">${esc(c)}</button>`).join('')}</div>`;}
function openHelpDialog(){if(!game?.helpPending)return;const h=game.helpPending,item=ITEM.get(h.itemId);const model=h.guided||h.tries>=2;modal(`<div class="modal-top"><h2>${esc(t('helpTitle'))}</h2><button class="closebtn" data-action="closeHelp" aria-label="${esc(t('cancel'))}">${icon('close',21)}</button></div><p>${esc(t('helpBody'))}</p><div class="help-meaning" lang="${game.support}" dir="${dir(game.support)}">${esc(supportText(item,game.target,game.support))}</div><p style="margin-top:14px">${esc(t('helpTask'))}</p>${model?`<div class="model-box" lang="${game.target}" dir="${dir(game.target)}">${esc(item.text[game.target])}</div><p>${esc(t('guided'))}</p>`:''}<textarea class="written" id="help-answer" lang="${game.target}" dir="${dir(game.target)}" maxlength="500" spellcheck="false" autocomplete="off" aria-label="${esc(t('yourAnswer'))}">${esc(h.answer||'')}</textarea>${keyboard(game.target)}${h.error?`<div class="note-warning">${esc(t(h.error))}</div>`:''}<div class="modal-actions"><button class="textbtn" data-action="helpModel">${esc(t('copyModel'))}</button>${button('checkHelp',t('check'),'check','coral')}</div><p class="tiny-note">${esc(t('networkPrivacy'))}</p>`,d=>{setTimeout(()=>d.querySelector('textarea')?.focus(),40);});}
function checkHelp(){if(!game?.helpPending)return;const h=game.helpPending,item=ITEM.get(h.itemId),answer=document.querySelector('#help-answer')?.value||'';h.answer=answer;
 if(!answer.trim()){h.error='empty';save();openHelpDialog();return;}
 if(!matchesText(item,answer,game.target)){h.tries++;h.error='unrecognised';save();openHelpDialog();return;}
 const kind=h.kind;game.helpPending=null;closeDialog();applyHelp(kind);toast(t('helpUnlocked'));}
function showModel(){if(!game)return;const item=game.mode==='complete'?unitItems(game.unit)[game.round]:unitItems(game.unit).find(i=>!game.completed.includes(i.id));if(!item)return;game.assist[item.id]=true;save();modal(`<div class="modal-top"><h2>${esc(t('model'))}</h2><button class="closebtn" data-action="closeDialog" aria-label="${esc(t('cancel'))}">${icon('close',21)}</button></div><p>${esc(t('supported'))}</p><div class="model-box" lang="${game.target}" dir="${dir(game.target)}">${esc(item.text[game.target])}</div><p style="margin:15px 0" lang="${game.support}" dir="${dir(game.support)}">${esc(supportText(item,game.target,game.support))}</p>${sounds(game.target,item.text[game.target],item.id)}<p class="tiny-note">${esc(t('buildLimit'))}</p>`);}
function finish(){
 const previousAwards=earnedBadges(store),previousBonus=progressionBonus(store.daily);
 const now=Date.now(),key=missionKey(game.unit,game.mode,game.route),previous=store.missions[key]?.score||0,accuracy=Math.round(game.results.length/Math.max(1,game.results.length+game.errors)*100),stars=accuracy>=90&&game.helpUses.hint===0?3:accuracy>=65?2:1;
 store.missions[key]={score:Math.max(previous,game.score),stars:Math.max(store.missions[key]?.stars||0,stars),done:true,date:now};
 const tour=store.tours[game.route];if(tour)store.tours[game.route]=advanceTour(tour,game);
 const activity=dayActivity(localDay(now));if(!activity.games.includes(game.id))activity.games.push(game.id);activity.bestCombo=Math.max(activity.bestCombo,game.bestCombo);const playedFormat=['pair','listen','write'].includes(game.mode)?game.tableFormat:'classic';if(!activity.formats.includes(playedFormat))activity.formats.push(playedFormat);
 if(game.challengeDay===localDay(now)){const old=activity.challenges[game.route];activity.challenges[game.route]={unit:game.unit,mode:game.mode,completed:true,score:Math.max(old?.score||0,game.score)};}
 for(const result of game.results){const k=memoryKey(game.route,game.mode,result.itemId);if(result.mistakes===0&&!result.assisted)recordIndependent(k,false,store.memory[k]?.due<=now);store.memory[k]=updateMemory(store.memory[k],result.mistakes===0,result.assisted,now);}
 const day=localDay(now);if(!store.days.includes(day))store.days.push(day);
 store.awards=earnedBadges(store);const bonus=progressionBonus(store.daily)-previousBonus;
 lastSummary={...clone(game),accuracy,stars,bonus,newBadges:store.awards.filter(id=>!previousAwards.includes(id)),xp:Math.floor((Math.max(previous,game.score)-previous)/10)+bonus};delete store.sessions[game.route];view='summary';game=null;save();render();window.scrollTo({top:0,behavior:'instant'});celebrate();
}
function summaryView(){if(!lastSummary)return homeView();const s=lastSummary,u=UNIT.get(s.unit),missed=s.results.filter(r=>r.assisted||r.mistakes);return `<section class="summary-wrap"><div class="summary-hero"><div class="trophy-tile">${icon('trophy',47)}</div><div class="eyebrow">${esc(modeName(s.mode))} / ${esc(title(s.unit))}</div><h1>${esc(t('completed'))}</h1><p>${esc(t('summaryLead'))}</p><div class="stars">${[1,2,3].map(n=>`<span style="opacity:${n<=s.stars?1:.22}">${icon('star',29)}</span>`).join('')}</div></div>${tourSummary(s)}${summaryRewards(s)}<div class="stats-grid"><div class="stat-card coral">${icon('spark',27)}<strong>+${s.xp}</strong><span>${esc(t('earnedXp'))}</span></div><div class="stat-card">${icon('shield',27)}<strong>${s.accuracy}%</strong><span>${esc(t('accuracy'))}</span></div><div class="stat-card purple">${icon('flame',27)}<strong>${s.bestCombo}</strong><span>${esc(t('bestCombo'))}</span></div></div><div class="rulebox"><div class="rulehead">${icon('hint',20)}${esc(t('learnedRule'))}</div><p lang="${s.support}" dir="${dir(s.support)}">${esc(u.rules[s.target][s.support])}</p></div><h3>${esc(t('yourDiscoveries'))}</h3>${s.results.map(r=>{const item=ITEM.get(r.itemId);return `<div class="result-row"><span class="result-mark">${icon('check',19)}</span><div class="result-content"><div class="targetline" lang="${s.target}" dir="${dir(s.target)}">${esc(item.text[s.target])}</div><div class="supportline" lang="${s.support}" dir="${dir(s.support)}">${esc(supportText(item,s.target,s.support))}</div><span class="status-tag">${esc(t(r.assisted?'supported':r.mistakes?'practising':'autonomous'))}</span></div>${sounds(s.target,item.text[s.target],item.id)}</div>`;}).join('')}<div class="missed-card"><h3>${icon('review',21)} ${esc(t('nextTime'))}</h3><p>${esc(t(missed.length?'errorsReview':'perfectNote'))}</p>${missed.map(r=>`<p><bdi lang="${s.target}">${esc(ITEM.get(r.itemId).text[s.target])}</bdi> · ${esc(t(r.assisted?'supported':'reviewError'))}</p>`).join('')}${(()=>{const item=s.results.map(r=>ITEM.get(r.itemId)).find(i=>(i.accepted[s.target]||[]).length>1);return item?`<p>${esc(t('model'))}: <bdi lang="${s.target}">${esc(item.accepted[s.target][1])}</bdi></p>`:'';})()}</div><p class="tiny-note">${esc(t('bestOnly'))}<br>${esc(t('summaryBody'))}</p><div class="summary-share">${button('shareChallenge',t('challengeFriend'),'globe','secondary')}${button('passport',t('passport'),'book','secondary')}</div><div class="summary-actions">${button('replay',t('replayLevel'),'review','secondary')}${button('nextMission',t('nextMission'),'arrow','coral')}</div></section>`;}
function dueEntries(){return Object.entries(store.memory).filter(([k,m])=>k.startsWith(route()+'|')&&MODES.includes(k.split('|')[1])&&m.due<=Date.now()).sort((a,b)=>a[1].due-b[1].due);}
function reviewView(){const due=dueEntries(),groups=new Map();for(const [k,m]of due){const [,mode,id]=k.split('|'),item=ITEM.get(id);if(!item||!UNIT.has(item.unitId))continue;const g=item.unitId+'|'+mode;if(!groups.has(g))groups.set(g,{unit:item.unitId,mode,n:0});groups.get(g).n++;}
 return `<div class="page-head"><div class="eyebrow">${esc(t('review'))}</div><h1>${esc(t('reviewTitle'))}</h1><p>${esc(t('reviewDesc'))}</p></div>${groups.size?[...groups.values()].map(g=>`<div class="review-card"><div class="review-count">${g.n}</div><div class="rtext"><h3>${esc(title(g.unit))}</h3><p>${esc(modeName(g.mode))} · ${esc(t('itemsDue',{n:g.n}))}</p></div>${button('intro',t('reviewStart'),'arrow','small',`data-unit="${g.unit}" data-mode="${g.mode}"`)}</div>`).join(''):`<div class="empty-state">${icon('review',48)}<p>${esc(t('noneDue'))}</p>${button('nav',t('path'),'arrow','secondary',`data-view="home"`)}</div>`}<div class="rulebox"><div class="rulehead">${icon('clock',20)}${esc(t('method'))}</div><p style="font-size:17px">${esc(t('methodText'))}</p></div>`;}
function notebookView(){const seen=COURSE.items.filter(i=>showAllNotebook||store.seen.includes(route()+'|'+i.id)),q=norm(search,store.settings.target),list=seen.filter(i=>!q||Object.values(i.text).some(v=>norm(v,store.settings.target).includes(q)));return `<div class="page-head"><div class="eyebrow">${esc(t('notebook'))}</div><h1>${esc(t('notebookTitle'))}</h1><p>${esc(t('notebookDesc'))}</p></div><div class="notebook-search"><input id="notebook-search" type="search" value="${esc(search)}" placeholder="${esc(t('search'))}" aria-label="${esc(t('search'))}"><button class="button secondary small" data-action="allPhrases">${icon(showAllNotebook?'check':'book',17)}${esc(t('allPhrases'))}</button></div><div id="notebook-items">${notebookItems(list)}</div>`;}
function notebookItems(list){if(!list.length)return `<div class="empty-state">${icon('book',45)}<p>${esc(t(search?'noResults':'emptyNotebook'))}</p>${button('nav',t('begin'),'arrow','',`data-view="home"`)}</div>`;return `<div class="notebook-grid">${list.map(i=>`<article class="example-card"><div class="eyebrow">${esc(title(i.unitId))}</div><div class="targetline" lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(i.text[store.settings.target])}</div><div class="supportline" lang="${store.settings.support}" dir="${dir(store.settings.support)}">${esc(supportText(i,store.settings.target,store.settings.support))}</div>${sounds(store.settings.target,i.text[store.settings.target],i.id)}</article>`).join('')}</div>`;}
function langSelect(id,value,label){return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}" ${store.settings.support===store.settings.target&&['setting-support','setting-ui'].includes(id)?'disabled':''}>${LANGS.map(l=>`<option value="${l}" ${l===value?'selected':''}>${NAMES[l]}</option>`).join('')}</select></div>`;}
function settingsView(){const s=store.settings;return `<div class="page-head"><div class="eyebrow">${esc(t('settings'))}</div><h1>${esc(t('settingsTitle'))}</h1><p>${esc(t('settingsDesc'))}</p></div><div class="settings-grid"><section class="settings-card"><h2>${icon('globe',24)} ${esc(t('currentRoute'))}</h2><div class="field"><label for="setting-journey">${esc(t('learningPath'))}</label><select id="setting-journey"><option value="bilingual" ${s.support!==s.target?'selected':''}>${esc(t('bilingual'))}</option><option value="mono" ${s.support===s.target?'selected':''}>${esc(t('mono'))}</option></select></div><p class="tiny-note">${esc(t('monoDesc'))}</p><div class="route-settings">${langSelect('setting-support',s.support,t('supportLanguage'))}<button class="swap" ${s.support===s.target?'disabled':''} data-action="swapSettings" aria-label="${esc(t('swap'))}">${icon('swap',23)}</button>${langSelect('setting-target',s.target,t('targetLanguage'))}</div>${langSelect('setting-ui',s.ui,t('uiLanguage'))}${button('applySettings',t('apply'),'check','wide')}<div style="margin-top:22px">${[['effects','muteFx'],['labels','labels'],['large','largeTiles']].map(([k,label])=>`<label class="setting-toggle"><span>${esc(t(label))}</span><input type="checkbox" data-setting="${k}" ${s[k]?'checked':''}></label>`).join('')}</div><p class="tiny-note">${esc(t('journeySub'))}</p></section><section class="settings-card"><h2>${icon('speaker',24)} ${esc(t('audioTitle'))}</h2><p class="tiny-note">${esc(t('audioDesc'))}</p>${LANGS.map(l=>`<div class="voice-row"><span class="langcoin ${MANIFEST.languages.includes(l)?'target':''}">${GLYPHS[l]}</span><div class="vname">${NAMES[l]}<small>${esc(t(MANIFEST.languages.includes(l)?'audioEmbedded':player.voice(l)?'audioDevice':'audioNeedPack'))}</small></div><button class="sound" data-action="speak" data-lang="${l}" data-text="${esc(ITEM.get('greetings_0').text[l])}" title="${esc(t('audioTest'))}" aria-label="${esc(t('audioTest')+' '+NAMES[l])}">${icon('speaker',18)}</button></div>`).join('')}<div class="field" style="margin-top:20px"><label for="voice-pref">${esc(t('audioChoose'))}</label><select id="voice-pref"><option value="offline" ${s.voice==='offline'?'selected':''}>${esc(t('offlineVoice'))}</option><option value="auto" ${s.voice==='auto'?'selected':''}>${esc(t('autoVoice'))}</option></select></div>${MANIFEST.missingLanguages.length?`<div class="note-warning">${esc(t('audioWarning'))}</div>`:''}<p class="tiny-note">${esc(t('voicePolicy'))}</p></section><section class="settings-card"><h2>${icon('shield',24)} ${esc(t('progressTitle'))}</h2><p class="tiny-note">${esc(t('localOnly'))}</p><div class="hero-actions" style="margin:20px 0">${button('export',t('export'),'download','secondary small')}${button('import',t('import'),'upload','secondary small')}<input id="import-file" type="file" accept="application/json,.json" hidden></div><p class="tiny-note">${esc(t('legacyNote'))}</p></section><section class="settings-card"><h2>${icon('hint',24)} ${esc(t('method'))}</h2><p class="tiny-note">${esc(t('methodText'))}</p><p class="tiny-note">${esc(t('qualityNote'))}</p><button class="textbtn" data-action="alpha">${icon('alpha',19)}${esc(t('alpha'))}</button></section></div>`;}
function applySettings(){let support=document.querySelector('#setting-support').value;const target=document.querySelector('#setting-target').value;const mono=document.querySelector('#setting-journey').value==='mono';if(mono)support=target;else if(support===target){toast(t('chooseDifferent'),true);return;}const ui=mono?target:document.querySelector('#setting-ui').value;store.settings={...store.settings,support,target,ui};save();render();toast(t('routeSaved'));}
