function learningEntry(){const mono=store.settings.target===store.settings.support;return `<section class="learning-entry" aria-label="${esc(t('learningStart'))}"><div><h2>${esc(t('learningStart'))}</h2><p>${esc(t('learningStartDesc'))}</p></div><div class="entry-actions">${button('alpha',t('fromAlphabet'),'alpha','secondary small')}${button('intro',t('fromPhrases'),'book','secondary small',`data-unit="${nextUnit().id}"`)}${!mono?button('mono',t('tryMono'),'globe','secondary small'): `<span class="mono-tag">${esc(t('mono'))} · ${esc(NAMES[store.settings.target])}</span>`}</div></section>`;}
function alphaCourse(){return ALPHABET[store.settings.target];}
