function alphaAudio(card){const lang=store.settings.target;return Boolean(player.entry(lang,card.speech,card.context||'')||player.voice(lang));}
function alphaCount(lesson,skill){const lang=store.settings.target;return lesson.cards.filter(card=>literacyMastered(store.memory,lang,skill,card)).length;}
function alphabetView(){const course=alphaCourse(),lang=store.settings.target,session=store.alphabetSessions[lang],due=Object.entries(store.memory).filter(([key,m])=>key.startsWith(`${lang}>${lang}|alpha_`)&&m.due<=Date.now()).length;return `<section class="literacy"><button class="textbtn" data-action="nav" data-view="home">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('alphabetPath'))} · <bdi>${NAMES[lang]}</bdi></h1><p>${esc(t('alphabetIntro'))}</p></div><div class="alpha-entry"><p>${esc(t('alphabetSessions'))}</p><div class="entry-actions">${button('alphaLesson',t('startLetters'),'alpha','',`data-lesson="${course.lessons[0].id}"`)}${button('alphaLesson',t('knowLetters'),'book','secondary',`data-lesson="first_words"`)}${session&&session.index<session.queue.length?button('alphaResume',t('resumeAlphabet'),'play','secondary'):''}</div></div><p class="alpha-review-count">${esc(t('alphaDue',{n:due}))}</p><details class="alpha-catalog" data-disclosure="alphabet-lessons" ${matchMedia(MOBILE_QUERY).matches?'':'open'}><summary>${esc(t('allLetterLessons'))}${icon('down',17)}</summary><ol class="alpha-lessons">${course.lessons.map((lesson,index)=>`<li><button class="alpha-lesson-row" data-action="alphaLesson" data-lesson="${lesson.id}"><span class="lesson-number">${index+1}</span><span class="lesson-label"><strong>${esc(lesson.title[store.settings.ui])}</strong><small>${esc(t('alphaCardCount',{n:lesson.cards.length}))}</small><span class="lesson-skills">${['recognize','write','listen'].map(skill=>`<span>${esc(t('alpha_'+skill))}: ${alphaCount(lesson,skill)}/${lesson.cards.length}</span>`).join('')}</span></span>${icon('arrow',20,'right-arrow')}</button></li>`).join('')}</ol></details><details class="alphabet-reference"><summary>${esc(t('fullAlphabet'))}</summary>${alphabetReference(course,lang)}</details><p class="tiny-note">${esc(t('alphabetScope'))}</p></section>`;}
function alphabetReference(course,lang){return `<div class="alphabet-table-wrap"><table class="alphabet-table" lang="${lang}" dir="${dir(lang)}"><caption>${esc(NAMES[lang])}</caption><thead><tr><th>${esc(t('letter'))}</th><th>${esc(t('letterName'))}</th>${lang==='ar'?['isolated','initial','medial','final'].map(key=>`<th>${esc(t('alpha_'+key))}</th>`).join(''):`<th>${esc(t('lowercase'))}</th>`}</tr></thead><tbody>${course.letters.map(row=>`<tr><td><bdi>${esc(row.symbol)}</bdi></td><td>${esc(row.name)}</td>${lang==='ar'?row.forms.map(form=>`<td>${form?`<bdi>${esc(form)}</bdi>`:`<span aria-label="${esc(t('noJoin'))}">—</span>`}</td>`).join(''):`<td>${esc(row.lower)}</td>`}</tr>`).join('')}</tbody></table></div>${lang==='ar'?`<p>${esc(t('noJoin'))}</p>`:''}`;}
function alphabetLessonView(){const lesson=alphaLesson(),lang=store.settings.target,available=lesson.cards.filter(alphaAudio).length;return `<section class="literacy"><button class="textbtn" data-action="alphaExit">${icon('back',18,'right-arrow')}${esc(t('alphabetPath'))}</button><div class="page-head"><h1>${esc(lesson.title[store.settings.ui])}</h1><p>${esc(lesson.note[store.settings.ui])}</p></div><div class="alphabet-models" dir="${dir(lang)}">${lesson.cards.map(card=>`<article class="alphabet-model"><div class="learn-symbol" lang="${lang}"><bdi>${esc(card.upper&&card.upper!==card.model?card.upper+' '+card.model:card.model)}</bdi></div><p lang="${lang}" dir="${dir(lang)}">${esc(card.cue)}</p><button class="sound" data-action="speak" data-lang="${lang}" data-text="${esc(card.speech)}" data-context="${esc(card.context||'')}" ${alphaAudio(card)?'':'disabled'} aria-label="${esc(t('listen')+': '+card.speech)}">${icon('speaker',20)}</button></article>`).join('')}</div><h2>${esc(t('alphaPractice'))}</h2><p class="alpha-instructions">${esc(t('alphabetSessions'))}</p><div class="alpha-practice-actions">${ALPHA_SKILLS.map(skill=>`<button class="button ${skill==='recognize'?'':'secondary'}" data-action="alphaStart" data-skill="${skill}" ${skill==='listen'&&!available?'disabled':''}>${icon(skill==='write'?'write':skill==='listen'?'ear':'alpha',20)}${esc(t('alpha_'+skill))}<span>${alphaCount(lesson,skill)}/${lesson.cards.length}</span></button>`).join('')}</div>${available<lesson.cards.length?`<p class="note-warning">${esc(t('alphaAudioNotice',{n:available,total:lesson.cards.length}))}</p>`:''}<p class="tiny-note">${esc(t('alphabetScope'))}</p>${button('intro',t('fromPhrases'),'arrow','secondary',`data-unit="${nextUnit().id}"`)}</section>`;}
function startAlphabet(skill){if(!ALPHA_SKILLS.includes(skill))return;const lesson=alphaLesson(),lang=store.settings.target,queue=literacyQueue(lesson,store.memory,lang,skill,alphaAudio);if(!queue.length){toast(t('audioUnavailable'),true);return;}store.alphabetSessions[lang]={lesson:lesson.id,skill,queue,index:0,answer:'',errors:0,assisted:false,heard:false,feedback:null};prepareAlphabet();}
function currentAlphabet(){const lang=store.settings.target,s=store.alphabetSessions[lang];const lesson=alphaCourse().lessons.find(l=>l.id===s?.lesson);return {lang,s,lesson,card:lesson?.cards.find(card=>card.id===s?.queue[s.index])};}
function alphabetQuizView(){const {lang,s,lesson,card}=currentAlphabet();if(!s||!lesson)return alphabetView();if(!card)return `<section class="literacy alpha-finished"><h1>${esc(t('alphaSessionDone'))}</h1><p>${esc(t('alphaSessionDoneDesc'))}</p><div class="entry-actions">${button('alphaLesson',t('continuePractice'),'arrow','',`data-lesson="${lesson.id}"`)}${button('alphaExit',t('alphabetPath'),'alpha','secondary')}</div></section>`;const typing=s.skill==='write';return `<section class="literacy alpha-quiz"><button class="textbtn" data-action="alphaExit">${icon('back',18,'right-arrow')}${esc(t('saveAndReturn'))}</button><div class="page-head"><h1>${esc(t('alpha_'+s.skill))}</h1><p>${esc(lesson.title[store.settings.ui])} · ${s.index+1}/${s.queue.length}</p></div><progress value="${s.index}" max="${s.queue.length}" aria-label="${esc(t('progress',{current:s.index,total:s.queue.length}))}"></progress><div class="alpha-question"><p>${esc(t(s.skill==='listen'?'alphaListenTask':typing?'alphaWriteTask':'alphaRecognizeTask'))}</p>${s.skill==='listen'?`<button class="button" data-action="alphaListen" ${alphaAudio(card)?'':'disabled'}>${icon('speaker',24)}${esc(t('listen'))}</button><p class="tiny-note">${esc(t('audioNeedListen'))}</p>`:`<div class="alpha-cue" lang="${lang}" dir="${dir(lang)}"><bdi>${esc(card.cue)}</bdi></div>`}${s.assisted?`<div class="model-box" lang="${lang}" dir="${dir(lang)}">${esc(card.model)}</div><p>${esc(t('guided'))}</p>`:''}</div>${typing?`<label class="alpha-answer-label" for="alpha-answer">${esc(t('yourAnswer'))}</label><input id="alpha-answer" lang="${lang}" dir="${dir(lang)}" value="${esc(s.answer)}" maxlength="100" spellcheck="false" autocomplete="off" autocapitalize="off" ${s.feedback===true?'disabled':''}>${s.feedback===true?'':alphabetKeyboard(lang)}${button('alphaCheck',t('check'),'check','',s.feedback===true?'disabled':'')}`:`<div class="alpha-choices" dir="${dir(lang)}">${literacyChoices(card,lesson).map(answer=>`<button data-action="alphaCheck" data-answer="${esc(answer)}" lang="${lang}" ${s.feedback===true?'disabled':''}><bdi>${esc(answer)}</bdi></button>`).join('')}</div>`}${s.feedback!==null?`<div class="alpha-feedback ${s.feedback?'correct':'incorrect'}" role="status">${esc(t(s.feedback?(s.assisted||s.errors?'alphaCorrectAssisted':'alphaCorrect'):'alphaIncorrect'))}</div>`:''}<div class="alpha-quiz-actions">${s.feedback===true?button('alphaNext',t('next'),'arrow'):button('alphaModel',t('copyModel'),'book','secondary')}</div><p class="tiny-note">${esc(t('strictAlphabet'))}</p></section>`;}
function alphabetKeyboard(lang){const chars={it:'abcdefghijklmnopqrstuvwxyzàèéìòù’',en:'abcdefghijklmnopqrstuvwxyz',ru:'абвгдеёжзийклмнопрстуфхцчшщъыьэюя\u0301',ar:'ابتثجحخدذرزسشصضطظعغفقكلمنهويءأإآؤئةى\u064e\u0650\u064f\u0652\u0651\u064b\u064c\u064d'}[lang];return `<div class="keyboard alphabet-keyboard" aria-label="${esc(t('keyboard'))}">${Array.from(chars).map(c=>`<button class="keybtn" data-action="key" data-char="${esc(c)}" aria-label="${esc(c)}">${esc(/[\u0301\u064b-\u0652]/u.test(c)?'◌'+c:c)}</button>`).join('')}<button class="keybtn" data-action="key" data-char=" ">${esc(t('space'))}</button></div>`;}
function checkAlphabet(answer){const {lang,s,lesson,card}=currentAlphabet();if(!card||s.feedback===true)return;if(s.skill==='listen'&&!s.heard){toast(t('audioNeedListen'),true);return;}const value=answer??document.querySelector('#alpha-answer')?.value??'';s.answer=value;if(!value.trim()){toast(t('empty'),true);return;}if(!literacyMatches(card,value)){s.errors++;store.memory[literacyKey(lang,s.skill,card.id)]=updateMemory(store.memory[literacyKey(lang,s.skill,card.id)],false,true);s.feedback=false;save();render();document.querySelector('#alpha-answer')?.focus();return;}const assisted=s.assisted||s.errors>0,key=literacyKey(lang,s.skill,card.id);if(!assisted)recordIndependent(key,true,store.memory[key]?.due<=Date.now());store.memory[key]=updateMemory(store.memory[key],true,assisted);store.awards=earnedBadges(store);s.feedback=true;const day=localDay();if(!store.days.includes(day))store.days.push(day);if(lesson.cards.every(c=>literacyMastered(store.memory,lang,s.skill,c))){const mission=`${lang}>${lang}|alpha_${s.skill}|${lesson.id}`;store.missions[mission]={score:lesson.cards.length*10,stars:3,done:true,date:Date.now()};}save();render();document.querySelector('[data-action="alphaNext"]')?.focus();}
function nextAlphabet(){const {s}=currentAlphabet();if(!s||s.feedback!==true)return;s.index++;s.answer='';s.errors=0;s.assisted=false;s.heard=false;s.feedback=null;save();render();document.querySelector('#alpha-answer')?.focus();}
function alphabetModel(){const {s,card}=currentAlphabet();if(!card||s.feedback===true)return;s.assisted=true;save();render();}
async function listenAlphabet(button){const {lang,s,card}=currentAlphabet();if(!card||s.skill!=='listen')return;const index=s.index;button.disabled=true;const ok=await player.speak(lang,card.speech,{context:card.context||'',preference:store.settings.voice});if(store.settings.target===lang&&store.alphabetSessions[lang]===s&&s.index===index&&view==='alphaQuiz'){s.heard=ok;save();render();}}
function exportProgress(){save();const data=JSON.stringify(cleanSaved(store),null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='parola-progressi-'+localDay()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importProgress(file){if(!file||file.size>8000000){toast(t('importError'),true);return;}try{const p=JSON.parse(await file.text());const imported=cleanSaved(p),merged=mergeProgress(store,imported);merged.sessions={...imported.sessions,...store.sessions};merged.alphabetSessions={...imported.alphabetSessions,...store.alphabetSessions};store=merged;save();render();toast(t('imported'));}catch{toast(t('importError'),true);}}

function beginWrite(tile){
 game.writePending={tileId:tile.id,itemId:tile.itemId,tries:0,answer:'',guided:false,error:false};save();openWriteDialog();
}
function openWriteDialog(){
 if(!game?.writePending)return;const w=game.writePending,item=ITEM.get(w.itemId),model=w.guided||w.tries>=2;
 if(model)game.assist[item.id]=true;
 modal(`<div class="modal-top"><h2>${esc(t('writeTitle'))}</h2><button class="closebtn" data-action="closeWrite" aria-label="${esc(t('cancel'))}">${icon('close',21)}</button></div><p>${esc(t('writePrompt'))}</p><div class="help-meaning" lang="${game.support}" dir="${dir(game.support)}">${esc(supportText(item,game.target,game.support))}</div>${model?`<div class="model-box" lang="${game.target}" dir="${dir(game.target)}">${esc(item.text[game.target])}</div><p>${esc(t('guided'))}</p>`:''}<textarea class="written" id="write-answer" lang="${game.target}" dir="${dir(game.target)}" maxlength="500" spellcheck="false" autocomplete="off" aria-label="${esc(t('yourAnswer'))}">${esc(w.answer)}</textarea>${keyboard(game.target)}${w.error?`<div class="note-warning">${esc(t(w.error))}</div>`:''}<div class="modal-actions"><button class="textbtn" data-action="writeModel">${esc(t('copyModel'))}</button>${button('checkWrite',t('check'),'check','coral')}</div>${sounds(game.target,item.text[game.target],item.id)}<p class="tiny-note">${esc(t('writeAudioNote'))}</p>`,d=>d.querySelector('textarea')?.focus());
 save();
}
function checkWrite(){
 if(!game?.writePending)return;const w=game.writePending,item=ITEM.get(w.itemId),answer=document.querySelector('#write-answer')?.value||'';w.answer=answer;
 if(!answer.trim()){w.error='empty';save();openWriteDialog();return;}
 if(!matchesText(item,answer,game.target)){w.tries++;game.errors++;game.tries++;game.combo=0;game.mistakes[item.id]=(game.mistakes[item.id]||0)+1;w.error='unrecognised';save();openWriteDialog();return;}
 if(w.guided||w.tries>=2)game.assist[item.id]=true;
 if(!game.revealed.includes(item.id))game.revealed.push(item.id);
 game.writePending=null;closeDialog();render();toast(t('writeUnlocked'));
}

document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='nav')nav(b.dataset.view);
 else if(a==='intro')intro(b.dataset.unit,b.dataset.mode);
 else if(a==='mode'&&!pendingChallenge&&!pendingTour&&!pendingInvite&&!pendingTutorial){selectedMode=b.dataset.mode;render();}
 else if(a==='freeStart'){selectedUnit=document.querySelector('#free-unit').value;intro(selectedUnit,selectedMode);}
 else if(a==='start')startGame();
 else if(a==='introNext')advancePreparation();
 else if(a==='homeTab')switchHomeTab(b.dataset.tab);
 else if(a==='dailyChallenge'){const challenge=todaysChallenge();intro(challenge.unit,challenge.mode,challenge);}
 else if(a==='tableFormat'&&!pendingChallenge&&!pendingTour&&!pendingInvite&&!pendingTutorial){store.settings.tableFormat=b.dataset.format;save();render();}
 else if(a==='achievements')nav('achievements');
 else if(a==='welcomeStart')completeWelcome();
 else if(a==='welcomeSkip'){store.onboarded=true;save();nav('home');}
 else if(a==='tour')beginTour();
 else if(a==='passport')nav('passport');
 else if(a==='acceptInvite')acceptInvitation();
 else if(a==='shareChallenge')await shareChallenge();
 else if(a==='copyChallenge')await copyChallenge();
 else if(a==='installApp')await installApp();
 else if(a==='resume')resume();
 else if(a==='leave'){save();nav('home');toast(t('saved'));}
 else if(a==='tile')pickTile(+b.dataset.id);
 else if(a==='downloadAudio')await warmAudio(null,true);
 else if(a==='tileAudio'){e.stopPropagation();await tileAudio(+b.dataset.id);}
 else if(a==='speak'){if(game?.writePending){game.assist[game.writePending.itemId]=true;save();}b.classList.add('playing');await player.speak(b.dataset.lang,b.dataset.text,{rate:+b.dataset.rate||1,preference:store.settings.voice,context:b.dataset.context||''});b.classList.remove('playing');}
 else if(a==='undo')undo();
 else if(a==='nextRound')nextRound();
 else if(a==='checkSentence')checkSentence();
 else if(a==='gameRules'){const unit=UNIT.get(game.unit);modal(`<div class="modal-top"><h2>${esc(t('ruleReminder'))}</h2><button class="closebtn" data-action="closeDialog" aria-label="${esc(t('cancel'))}">${icon('close',21)}</button></div><p lang="${game.support}" dir="${dir(game.support)}">${esc(unit.rules[game.target][game.support])}</p><p class="tiny-note">${esc(t('boardRules'))}</p>`);}
 else if(a==='help')requestHelp(b.dataset.kind);
 else if(a==='checkHelp')checkHelp();
 else if(a==='checkWrite')checkWrite();
 else if(a==='writeModel'&&game?.writePending){game.writePending.guided=true;game.assist[game.writePending.itemId]=true;save();openWriteDialog();}
 else if(a==='closeWrite'){closeDialog();if(game)game.writePending=null;save();}
 else if(a==='closeHelp'){closeDialog();if(game)game.helpPending=null;save();}
 else if(a==='helpModel'&&game?.helpPending){game.helpPending.guided=true;save();openHelpDialog();}
 else if(a==='closeDialog')closeDialog();
 else if(a==='key'){const ta=document.querySelector('#help-answer, #write-answer, #alpha-answer');if(ta){ta.setRangeText(b.dataset.char,ta.selectionStart,ta.selectionEnd,'end');ta.focus();if(ta.id==='alpha-answer'){const session=store.alphabetSessions[store.settings.target];if(session)session.answer=ta.value;}if(game?.helpPending)game.helpPending.answer=ta.value;if(game?.writePending)game.writePending.answer=ta.value;save();}}
 else if(a==='model')showModel();
 else if(a==='transcript'){game.transcript=true;for(const id of game.pool.filter(id=>!game.completed.includes(id)))game.assist[id]=true;render();toast(t('supported'));}
 else if(a==='replay')intro(lastSummary.unit,lastSummary.mode);
 else if(a==='nextMission'){const i=MODES.indexOf(lastSummary.mode);if(i<MODES.length-1)intro(lastSummary.unit,MODES[i+1]);else intro(COURSE.units[Math.min(23,UNIT.get(lastSummary.unit).index+1)].id,'pair');}
 else if(a==='applySettings')applySettings();
 else if(a==='swapSettings'){const x=document.querySelector('#setting-support'),y=document.querySelector('#setting-target');[x.value,y.value]=[y.value,x.value];}
 else if(a==='export')exportProgress();
 else if(a==='import')document.querySelector('#import-file')?.click();
 else if(a==='allPhrases'){showAllNotebook=!showAllNotebook;render();}
 else if(a==='alpha')alphaDialog();
 else if(a==='mono')Parola.setRoute(store.settings.target,store.settings.target,store.settings.target);
 else if(a==='alphaLesson'){alphaLessonId=b.dataset.lesson;nav('alphaLesson');}
 else if(a==='alphaStart')startAlphabet(b.dataset.skill);
 else if(a==='alphaResume'){alphaLessonId=store.alphabetSessions[store.settings.target]?.lesson;prepareAlphabet();}
 else if(a==='alphaCheck')checkAlphabet(b.dataset.answer);
 else if(a==='alphaNext')nextAlphabet();
 else if(a==='alphaModel')alphabetModel();
 else if(a==='alphaListen')await listenAlphabet(b);
 else if(a==='alphaExit')nav('alphabet');
});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-action=homeTab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...root.querySelectorAll('[data-action=homeTab]')],index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;switchHomeTab(tabs[next].dataset.tab);tabs[next].focus();return;}const tile=e.target.closest('.tile');if(tile&&!e.target.closest('.tileaudio')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const origin=tile.getBoundingClientRect(),axis=e.key==='ArrowLeft'||e.key==='ArrowRight'?'x':'y',sign=e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1;const candidates=[...document.querySelectorAll('.tile[data-free=true]:not(.gone)')].filter(el=>el!==tile).map(el=>{const r=el.getBoundingClientRect(),dx=r.x-origin.x,dy=r.y-origin.y;return{el,distance:Math.abs(axis==='x'?dx:dy)+Math.abs(axis==='x'?dy:dx)*3,direction:(axis==='x'?dx:dy)*sign}}).filter(c=>c.direction>1).sort((a,b)=>a.distance-b.distance);candidates[0]?.el.focus({preventScroll:true});candidates[0]?.el.scrollIntoView({block:'nearest',inline:'nearest'});return;}if(tile&&!e.target.closest('.tileaudio')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();pickTile(+tile.dataset.id);}if(e.target.id==='alpha-answer'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();checkAlphabet();}if(e.target.id==='write-answer'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();checkWrite();}if(e.target.id==='help-answer'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();checkHelp();}});
document.addEventListener('change',e=>{const el=e.target;if(['welcome-target','welcome-support','setting-target','setting-support'].includes(el.id)){const target=document.querySelector('#welcome-target, #setting-target')?.value||store.settings.target,support=document.querySelector('#welcome-support, #setting-support')?.value||store.settings.support;audioPacks.select([target,support]);}if(el.dataset.setting){store.settings[el.dataset.setting]=el.checked;save();}if(el.id==='setting-journey'){const mono=el.value==='mono';document.querySelector('#setting-support').disabled=mono;document.querySelector('[data-action=swapSettings]').disabled=mono;document.querySelector('#setting-ui').disabled=mono;}if(el.id==='voice-pref'){store.settings.voice=el.value;save();}if(el.id==='free-unit')selectedUnit=el.value;if(el.id==='import-file')importProgress(el.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='alpha-answer'){const session=store.alphabetSessions[store.settings.target];if(session){session.answer=e.target.value;save();}}if(e.target.id==='write-answer'&&game?.writePending){game.writePending.answer=e.target.value;save();}if(e.target.id==='help-answer'&&game?.helpPending){game.helpPending.answer=e.target.value;save();}if(e.target.id==='notebook-search'){search=e.target.value;const q=norm(search,store.settings.target);const list=COURSE.items.filter(i=>(showAllNotebook||store.seen.includes(route()+'|'+i.id))&&(!q||Object.values(i.text).some(v=>norm(v,store.settings.target).includes(q))));document.querySelector('#notebook-items').innerHTML=notebookItems(list);}});
